namespace docking.widgets.tree.support;







using docking;
using docking;
using docking.widgets.tree;

public class GTreeCellEditor : DefaultTreeCellEditor {

	private UndoRedoKeeper undoRedoKeeper;

	public GTreeCellEditor(JTree tree, DefaultTreeCellRenderer renderer) : base(tree, renderer)
    {

		if (realEditor is DefaultCellEditor) {
			Component c = ((DefaultCellEditor) realEditor).getComponent();
			if (c is JTextField) {
				JTextField tf = (JTextField) c;
				undoRedoKeeper = DockingUtils.installUndoRedo(tf);
			}
		}
	}

	/* @Override */
	public bool stopCellEditing() {
		if (base.stopCellEditing()) {
			clearUndoRedo();
			return true;
		}
		return false;
	}

	/* @Override */
	public void cancelCellEditing() {
		base.cancelCellEditing();
		clearUndoRedo();
	}

	private void clearUndoRedo() {
		if (undoRedoKeeper != null) {
			undoRedoKeeper.clear();
		}
	}

	/* @Override */
	public Component getTreeCellEditorComponent(JTree jTree, object value, bool isSelected,
			bool expanded, bool leaf, int row) {

		GTreeNode node = (GTreeNode) value;
		if (node.isLeaf()) {
			renderer.setLeafIcon(node.getIcon(expanded));
		}
		else {
			renderer.setOpenIcon(node.getIcon(true));
			renderer.setClosedIcon(node.getIcon(false));
		}

		return base.getTreeCellEditorComponent(jTree, value, isSelected, expanded, leaf, row);
	}

}
